-- Esquema reconstruido a partir de models/ y datos de ejemplo ficticios para la demo local.
-- No es el esquema original. Usuario de prueba: admin@demo.test / demo1234
CREATE DATABASE IF NOT EXISTS club_demo CHARACTER SET utf8mb4; USE club_demo;
CREATE TABLE categorias(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(60));
CREATE TABLE dias(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(30));
CREATE TABLE horas(id INT AUTO_INCREMENT PRIMARY KEY,hora VARCHAR(20));
CREATE TABLE paquetes(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(30));
CREATE TABLE equipacion(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(60));
CREATE TABLE rangos(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(20));
CREATE TABLE entrenadores(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(40),apellido VARCHAR(40),carnet_entrenador VARCHAR(20),email VARCHAR(60),telefono VARCHAR(20),imagen VARCHAR(40),redes TEXT);
CREATE TABLE patrocinadores(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(60),descripcion TEXT,logo VARCHAR(40),rango_id INT,url VARCHAR(120));
CREATE TABLE eventos(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120),descripcion TEXT,disponibles INT,categoria_id INT,dia_id INT,hora_id INT,entrenador_id INT,imagen VARCHAR(40));
CREATE TABLE usuarios(id INT AUTO_INCREMENT PRIMARY KEY,dni VARCHAR(12),nombre VARCHAR(60),apellido1 VARCHAR(60),apellido2 VARCHAR(60),email VARCHAR(60),password VARCHAR(60),confirmado TINYINT(1),estado VARCHAR(20),token VARCHAR(15),admin TINYINT(1),padre VARCHAR(60),correo_padre VARCHAR(60),madre VARCHAR(60),correo_madre VARCHAR(60),telefono VARCHAR(20),genero VARCHAR(10),fecha_nacimiento DATE,direccion VARCHAR(120),codigo_postal VARCHAR(10),ciudad VARCHAR(40),pais VARCHAR(40),nacionalidad VARCHAR(40),categoria VARCHAR(40),grupo VARCHAR(40),federado VARCHAR(5),nadar VARCHAR(5),alergias TEXT,informacion TEXT,imagen VARCHAR(40),tags VARCHAR(120),redes TEXT);
CREATE TABLE registros(id INT AUTO_INCREMENT PRIMARY KEY,paquete_id INT,pago_id VARCHAR(30),token VARCHAR(8),usuario_id INT,equipacion_id INT);
CREATE TABLE eventos_registros(id INT AUTO_INCREMENT PRIMARY KEY,evento_id INT,registro_id INT);
CREATE TABLE renovaciones(id INT AUTO_INCREMENT PRIMARY KEY,usuario_id INT,fecha_solicitud DATETIME,estado VARCHAR(20),fecha_respuesta DATETIME);
CREATE TABLE firmas(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(60),apellido1 VARCHAR(60),envioComu VARCHAR(5),imgRDS VARCHAR(5),imgPWeb VARCHAR(5),imgStr VARCHAR(5),iWHATS VARCHAR(5),ip VARCHAR(45),hora DATETIME,usuario_id INT,token VARCHAR(32),token_padre VARCHAR(32),confirmacion_padre VARCHAR(20),token_madre VARCHAR(32),confirmacion_madre VARCHAR(20),estado VARCHAR(20));
CREATE TABLE inscripciones_jugadores(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(60),email VARCHAR(60),telefono VARCHAR(20),evento_id INT,estado VARCHAR(20));
CREATE TABLE inscripciones_clubs(id INT AUTO_INCREMENT PRIMARY KEY,nombre_club VARCHAR(60),informacion_contacto TEXT,evento_id INT,estado VARCHAR(20));
